  ('5b197aad-d150-563c-ab9e-c3e0ca68dfcb', null, (select id from public.skills where slug = 'read-g7-authors-purpose'), null, 'medium',
   $q$What reason do some local historians give for keeping the sign the same?$q$, $q$[{"text":"Marisol only helped on the single stormy night in the year 1888.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The job officially belonged to the captain, and he was the one paid.","is_correct":true},{"text":"The museum cannot afford to make any new signs for several years.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Marisol's letters to her cousin were lost and cannot be checked now.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$The job officially belonged to the captain, and he was the one paid.$q$, $q$The historians "point out that the job officially belonged to the captain, and that the government paid him." The passage says the museum is planning new signs next year, so cost is not their reason.$q$, 'draft', 'eafa22fb-ff01-57f2-a13a-058b0e050868')
