-- Passage rg7-character-setting-plot-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('d99e08b5-a05b-5f90-9ae2-5844bed4ada3', 'rg7-character-setting-plot-p02', (select id from public.skills where slug = 'read-g7-character-setting-plot'), null,
        '6-8', $q$Low Tide at Kessick Point$q$, $q$My grandfather reads the tide chart
the way other people read the news.
At breakfast he taps a number, 6:40,
and says we have two hours, no more.

So we leave our toast half eaten.
We pull on boots that still smell of salt,
and we walk out where the sea has stepped back,
across mud that shines like a wet plate.

Out here everything is in a hurry.
Crabs slide sideways into their holes.
Snails write slow lines that the water will erase.
Grandfather points, names, and keeps one eye on the sand bar.

I want to stay by the pool where a starfish sleeps.
I want to draw it, every orange arm.
But the first thin stream is already curling back
around my boots, and Grandfather says, Now.

We walk, not run, the way he taught me,
the bucket swinging, the mud pulling at each step.
At the seawall I turn and watch the flats disappear,
the starfish pool gone under silver water.

Next time, I tell him, I will draw faster.
He laughs and folds the tide chart into my hand.$q$, 'draft')
