  ('4afe2a93-b995-5a30-9dc7-73252ad4f8d6', null, (select id from public.skills where slug = 'read-g7-evidence-inference'), null, 'medium',
   $q$Based on the passage, what can the reader infer about why gas lighting let shops stay open later?$q$, $q$[{"text":"Shoppers were more willing to be out in the evening once the streets were lit.","is_correct":true},{"text":"Shop owners paid the lamplighters to keep their lamps burning all night.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Gas lamps inside shops were brighter than the electric lights that came later.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Shops were required to close when the lamplighter turned the lamps off.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Shoppers were more willing to be out in the evening once the streets were lit.$q$, $q$The passage says shops stayed open later and "people felt safer walking after dark," so lit streets likely brought evening customers. Nothing in the text says shop owners paid lamplighters.$q$, 'draft', '5a0745b1-5ec2-5359-a0f2-84878d4b04ea')
