values
  ('e837a6d4-49d8-552a-8e6e-964b14186d6d', null, (select id from public.skills where slug = 'read-g7-figurative-language'), null, 'hard',
   $q$The coach's advice, "Be the tortoise early, and the hare at the end," alludes to a fable about a race. Based on the passage, what does the coach mean?$q$, $q$[{"text":"Expect to lose some races, because every runner has slow days.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Run as fast as possible at the start, then rest during the middle.","is_correct":false,"misconception_token":"reverses-allusion"},{"text":"Choose a running partner and take turns leading during the race.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Run at a steady, careful pace first, then speed up near the finish.","is_correct":true}]$q$::jsonb, $q$Run at a steady, careful pace first, then speed up near the finish.$q$, $q$The coach told Kiona "to save her energy for the final lap," so the slow, steady tortoise stands for the early laps and the speedy hare for the finish. Starting fast reverses the order the coach gives.$q$, 'draft', '1f6d4ece-73f1-5f36-a628-23e0cc35acf1')
