values
  ('6079ae20-9d88-5351-ada0-c6cedf9c271f', null, (select id from public.skills where slug = 'read-g7-figurative-language'), null, 'medium',
   $q$The author calls the wax comb "the city's housing and its warehouse at the same time." What relationship does this analogy show?$q$, $q$[{"text":"The comb is where the bees hold meetings to make group decisions.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The comb is both where young bees grow and where food is stored.","is_correct":true},{"text":"The comb is built by people and sold to the bees as a home.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The comb is where foragers dance to share news about flowers.","is_correct":false,"misconception_token":"wrong-detail"}]$q$::jsonb, $q$The comb is both where young bees grow and where food is stored.$q$, $q$Housing is where people live and a warehouse stores goods, matching cells that "hold growing young bees" and others that "store honey for winter." The dance is described in a different paragraph and is not part of this comparison.$q$, 'draft', '8cafda76-e587-5302-bd0a-4cd85cba334e')
